// makes the second action free and lets `r` go (§3.26).
func (m Model) confirmStopOrRestart() (tea.Model, tea.Cmd) {
	c := m.getSelectedContainer()
	if c == nil {
		return m, nil
	}
	if m.containerTable.IsBusy(c.ID) {
		return m, m.footer.Warn(busyMessage)
