	cmd := func() tea.Msg { return msgSlice{1, 2, 3} }

	msgs := Msgs(cmd)
	if len(msgs) != 1 {
		t.Fatalf("Msgs() returned %d messages, want the slice kept whole", len(msgs))
	}
	if _, ok := msgs[0].(msgSlice); !ok {
		t.Errorf("Msgs()[0] = %T, want msgSlice", msgs[0])
	}
}

